def parse_benchmarks(path):
    results = {}
    for line in open(path):
        if not line.startswith("Benchmark"):
            continue
        parts = line.split()
        if len(parts) < 8:
            continue
        try:
            name = parts[0]
            ns = float(parts[2])
            bop = int(parts[4])
            allocs = int(parts[6])
            results[name] = (ns / 1e6, bop, allocs)
        except (ValueError, IndexError):
